import React, { useEffect, useState, useMemo } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import sorsuLogo from "../assets/sorsu-logo.png";

const API_URL = "http://localhost:5000";

const THEME = {
  primary: "#B11226",
  primaryDark: "#8E0E1E",
  background: "#F8F9FA",
  white: "#FFFFFF",
};

function VotingPage({ auth }) {
  const [candidates, setCandidates] = useState([]);
  const [selected, setSelected] = useState({});
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [hasVoted, setHasVoted] = useState(false);

  const [showModal, setShowModal] = useState(false);
  const [modalMessage, setModalMessage] = useState("");
  const [modalType, setModalType] = useState("confirm");

  const navigate = useNavigate();

  // ======================
  // FETCH DATA
  // ======================
  useEffect(() => {
    const fetchData = async () => {
      try {
        const resCandidates = await axios.get(`${API_URL}/api/candidates`);
        setCandidates(resCandidates.data);

        if (auth?.token) {
          const resVotes = await axios.get(`${API_URL}/api/votes/my`, {
            headers: { Authorization: `Bearer ${auth.token}` },
          });

          const selectedVotes = {};
          resVotes.data.forEach((v) => {
            selectedVotes[v.position] = String(v.candidateId); // ✅ FIX
          });

          setSelected(selectedVotes);
          if (resVotes.data.length > 0) setHasVoted(true);
        }
      } catch (err) {
        console.error(err);
      }
      setLoading(false);
    };

    fetchData();
  }, [auth?.token]);

  // ======================
  // GROUP CANDIDATES
  // ======================
  const groupedCandidates = useMemo(() => {
    return candidates.reduce((groups, candidate) => {
      const position = candidate.candidacy;
      if (!groups[position]) groups[position] = [];
      groups[position].push(candidate);
      return groups;
    }, {});
  }, [candidates]);

  // ======================
  // SELECT
  // ======================
  const handleSelect = (position, candidateId) => {
    if (hasVoted) return;

    setSelected((prev) => ({
      ...prev,
      [position]:
        prev[position] === String(candidateId)
          ? null
          : String(candidateId),
    }));
  };

  // ======================
  // CAST VOTE
  // ======================
  const handleCastVote = () => {
    if (!auth?.token) {
      setModalType("error");
      setModalMessage("You must be logged in.");
      setShowModal(true);
      return;
    }

    if (hasVoted) {
      setModalType("error");
      setModalMessage("You already voted.");
      setShowModal(true);
      return;
    }

    if (Object.values(selected).filter(Boolean).length === 0) {
      setModalType("error");
      setModalMessage("Select candidates first.");
      setShowModal(true);
      return;
    }

    setModalType("confirm");
    setModalMessage("Are you sure you want to cast your vote?");
    setShowModal(true);
  };

  // ======================
  // CONFIRM VOTE
  // ======================
  const confirmVote = async () => {
    try {
      setSubmitting(true);

      await axios.post(
        `${API_URL}/api/votes/batch`,
        { candidateIds: Object.values(selected).filter(Boolean) },
        { headers: { Authorization: `Bearer ${auth.token}` } }
      );

      setHasVoted(true);
      setShowModal(false);

      // ✅ REDIRECT TO BALLOT
      navigate("/my-votes");

    } catch (err) {
      console.error(err);
      setModalType("error");
      setModalMessage(
        err.response?.data?.message || "Vote failed."
      );
      setShowModal(true);
    } finally {
      setSubmitting(false);
    }
  };

  if (loading) return <div style={{ padding: 50 }}>Loading...</div>;

  return (
    <div style={{ backgroundColor: THEME.background, minHeight: "100vh" }}>
      <div style={{ textAlign: "center", padding: 20 }}>
        <img src={sorsuLogo} alt="" style={{ height: 50 }} />
        <h2>OFFICIAL CANDIDATES LIST</h2>
      </div>

      <div style={{ padding: 40 }}>
        {Object.entries(groupedCandidates).map(([position, list]) => (
          <div key={position}>
            <h3>{position}</h3>

            <div style={{ display: "flex", gap: 20 }}>
              {list.map((c) => {
                const isSelected =
                  selected[position] === String(c._id);

                return (
                  <div
                    key={c._id}
                    onClick={() => handleSelect(position, c._id)}
                    style={{
                      width: 200,
                      padding: 10,
                      border: isSelected
                        ? "3px solid red"
                        : "1px solid #ccc",
                      cursor: "pointer",
                    }}
                  >
                    <h4>{c.firstName} {c.lastName}</h4>
                  </div>
                );
              })}
            </div>
          </div>
        ))}

        {!hasVoted && (
          <button onClick={handleCastVote}>
            {submitting ? "Submitting..." : "Cast Vote"}
          </button>
        )}
      </div>

      {/* MODAL */}
      {showModal && (
        <div style={modalStyles.overlay}>
          <div style={modalStyles.modal}>
            <p>{modalMessage}</p>

            {modalType === "confirm" ? (
              <>
                <button onClick={() => setShowModal(false)}>Cancel</button>
                <button onClick={confirmVote}>Confirm</button>
              </>
            ) : (
              <button onClick={() => setShowModal(false)}>OK</button>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

const modalStyles = {
  overlay: {
    position: "fixed",
    inset: 0,
    background: "rgba(0,0,0,0.5)",
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
  },
  modal: {
    background: "#fff",
    padding: 20,
  },
};

export default VotingPage;
